#!/usr/bin/env python3
"""Generate deterministic SystemVerilog constants for the Phase 5H mixer."""

from __future__ import annotations

from argparse import ArgumentParser
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from verification.apu_mixer import (  # noqa: E402
    TND_LAST_SEGMENT,
    pulse_lut_value,
    tnd_segment_value,
)


def render_lut_package() -> str:
    lines = [
        "// Generated by scripts/generate_apu_mixer_luts.py. Do not edit.",
        "`timescale 1ns/1ps",
        "package nes_apu_mixer_lut_pkg;",
        "    function automatic logic [19:0] apu_pulse_mix_lut(",
        "        input logic [4:0] pulse_sum",
        "    );",
        "        case (pulse_sum)",
    ]
    for pulse_sum in range(31):
        lines.append(
            f"            5'd{pulse_sum}: apu_pulse_mix_lut = "
            f"20'h{pulse_lut_value(pulse_sum):05x};"
        )
    lines.extend(
        [
            "            default: apu_pulse_mix_lut = 20'h00000;",
            "        endcase",
            "    endfunction",
            "",
            "    // Packed as {Q0.20 base, unsigned Q0.20 delta}.",
            "    function automatic logic [31:0] apu_tnd_segment_lut(",
            "        input logic [8:0] segment_index",
            "    );",
            "        case (segment_index)",
        ]
    )
    for segment_index in range(TND_LAST_SEGMENT + 1):
        base, delta = tnd_segment_value(segment_index)
        lines.append(
            f"            9'd{segment_index}: apu_tnd_segment_lut = "
            f"{{20'h{base:05x}, 12'h{delta:03x}}};"
        )
    last_base, last_delta = tnd_segment_value(TND_LAST_SEGMENT)
    lines.extend(
        [
            "            default: apu_tnd_segment_lut = "
            f"{{20'h{last_base:05x}, 12'h{last_delta:03x}}};",
            "        endcase",
            "    endfunction",
            "endpackage",
            "",
        ]
    )
    return "\n".join(lines)


def main() -> int:
    parser = ArgumentParser()
    parser.add_argument(
        "output",
        nargs="?",
        type=Path,
        default=ROOT / "rtl/apu/nes_apu_mixer_lut_pkg.sv",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="fail if the existing output differs from regenerated contents",
    )
    args = parser.parse_args()
    rendered = render_lut_package()
    if args.check:
        if not args.output.exists() or args.output.read_text(encoding="ascii") != rendered:
            print(f"ERROR: stale generated mixer LUT: {args.output}", file=sys.stderr)
            return 1
        print(f"Mixer LUT is reproducible: {args.output}")
        return 0
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(rendered, encoding="ascii", newline="\n")
    print(f"Generated {31} pulse and {TND_LAST_SEGMENT + 1} TND entries: {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
